<template>
  <main class="public-views">
    <header class="public-views-hero" data-scroll-group data-scroll-step="28">
      <h1>See Henry through <span>your own lens</span></h1>
      <div class="public-views-hero-copy">
      <p class="public-views-dek">Begin with a question, theme, or curiosity. AI searches Henry&rsquo;s work, research, experiences, and fragments, then composes a focused <AiViewTerm class="view-term-definition" /> around your perspective. Each <AiViewTerm /> keeps its original sources visible, and visitors can choose to share what they create here.</p>
      <button class="public-views-invitation" type="button" @click="createOwnView">
        <span class="public-views-invitation-copy">Compose your own <AiViewTerm /></span>
        <ArrowUpRightIcon class="public-views-invitation-arrow" />
      </button>
      </div>
    </header>

    <section id="public-views-collection" class="public-views-collection" aria-labelledby="public-views-collection-title">
      <div class="public-views-collection-heading" data-scroll-reveal>
        <div>
          <div class="public-views-title-line">
            <h2 id="public-views-collection-title">Public <AiViewTerm plural /></h2>
            <button
              class="public-views-admin-trigger"
              type="button"
              aria-label="Open collection management"
              :aria-expanded="adminLoginOpen || adminMode"
              @click="openAdminLogin"
            >
              <span aria-hidden="true">✦</span>
            </button>
          </div>
          <p v-if="!reading || !reading.text">See how other visitors have looked across Henry&rsquo;s work, experiences, and ideas.</p>
          <p v-else>{{ reading.text }}</p>
        </div>
      </div>
      <Transition name="public-admin-panel">
        <form v-if="adminLoginOpen && !adminMode" class="public-views-admin-login" @submit.prevent="loginAdmin">
          <div>
            <strong>Curate Shared Views</strong>
            <p>Enter the collection password to manage what appears here.</p>
          </div>
          <label>
            <span class="sr-only">Collection password</span>
            <input
              ref="adminPassword"
              v-model="adminPassword"
              type="password"
              autocomplete="current-password"
              placeholder="Password"
              :disabled="adminBusy"
            />
          </label>
          <button type="submit" :disabled="adminBusy || !adminPassword">{{ adminBusy ? 'Checking…' : 'Continue' }}</button>
          <button class="public-views-admin-close" type="button" aria-label="Close" @click="closeAdminLogin">×</button>
          <p v-if="adminError" class="public-views-admin-error" role="alert">{{ adminError }}</p>
        </form>
      </Transition>
      <div v-if="adminMode" class="public-views-admin-bar">
        <div>
          <strong>Curating collection</strong>
          <span>{{ publicAdminCount }} public · {{ hiddenAdminCount }} hidden</span>
        </div>
        <button type="button" :disabled="loading" @click="refreshAdminViews">Refresh</button>
        <button type="button" @click="signOutAdmin">Sign out</button>
      </div>
      <div v-if="adminMode" class="public-views-reading-admin">
        <div>
          <strong>Recent curiosity</strong>
          <p>Refresh the short note with recent public questions.</p>
          <p v-if="readingMessage" class="public-views-reading-message" role="status">{{ readingMessage }}</p>
        </div>
        <button type="button" :disabled="readingBusy || !publicAdminCount" @click="updateReading">
          <span v-if="readingBusy" class="reading-update-dot" aria-hidden="true"></span>
          {{ readingBusy ? 'Updating note…' : 'Update note' }}
        </button>
      </div>
      <div class="timeline-tools public-views-tools" data-scroll-reveal>
        <label class="timeline-search public-views-search" :aria-label="adminMode ? 'Search managed Views' : 'Search public Views'">
          <input v-model="query" class="timeline-search-input" type="search" autocomplete="off" spellcheck="false" :placeholder="adminMode ? 'Search all managed Views' : 'Search the collection'" />
          <i class="fa fa-search timeline-search-icon" aria-hidden="true"></i>
        </label>
      </div>

      <div v-if="loading" class="public-views-status">Loading Public <AiViewTerm plural />…</div>
      <div v-else-if="error" class="public-views-status">
        <p role="status">{{ error }}</p>
        <button class="public-views-retry" type="button" @click="refreshViews()">Try again</button>
      </div>
      <div v-else-if="searching" class="public-views-status">Looking through public <AiViewTerm plural />…</div>
      <TransitionGroup
        v-else-if="visibleViews.length"
        appear
        tag="ol"
        name="public-view-reveal"
        class="public-views-list"
        :class="{ 'is-curating': adminMode }"
      >
        <li
          v-for="(view, index) in visibleViews"
          :key="view.id"
          :class="{ 'is-admin-hidden': adminMode && view.visibility === 'hidden', 'is-admin-pending': pendingViewId === view.id }"
          :style="{ '--public-view-delay': `${Math.min(index, 6) * 28}ms` }"
        >
          <router-link
            :to="`/view/${view.id}`"
            class="public-view-link"
            :class="{ 'has-illustration': view.illustration && view.illustration.src }"
          >
            <figure v-if="view.illustration && view.illustration.src" class="public-view-plate">
              <img
                :src="view.illustration.src"
                :alt="view.illustration.alt || ''"
                loading="lazy"
                decoding="async"
              />
            </figure>
            <div class="public-view-body">
              <span class="public-view-question">&ldquo;{{ view.question }}&rdquo;</span>
              <strong>{{ view.title }}</strong>
              <span class="public-view-meta">{{ sourceLabel(view.source_count) }} · {{ dateLabel(view.created_at) }} <ArrowUpRightIcon /></span>
            </div>
          </router-link>
          <div
            v-if="adminMode"
            class="public-view-admin-controls"
            role="group"
            :aria-label="`Manage ${view.title}`"
          >
            <span class="public-view-visibility" :class="`is-${view.visibility}`">{{ view.visibility === 'public' ? 'Public' : 'Hidden' }}</span>
            <button type="button" :disabled="view.visibility !== 'public' || publicPosition(view.id) === 0 || Boolean(pendingViewId)" @click="pinView(view)">Top</button>
            <button type="button" :disabled="view.visibility !== 'public' || publicPosition(view.id) === 0 || Boolean(pendingViewId)" @click="moveView(view, -1)">Earlier</button>
            <button type="button" :disabled="view.visibility !== 'public' || publicPosition(view.id) === publicAdminCount - 1 || Boolean(pendingViewId)" @click="moveView(view, 1)">Later</button>
            <button type="button" :disabled="Boolean(pendingViewId)" @click="toggleViewVisibility(view)">{{ view.visibility === 'public' ? 'Hide' : 'Publish' }}</button>
            <button class="is-destructive" type="button" :disabled="Boolean(pendingViewId)" @click="deleteView(view)">Delete</button>
          </div>
        </li>
      </TransitionGroup>
      <p v-else-if="query.trim()" class="public-views-status">No {{ adminMode ? 'managed' : 'public' }} <AiViewTerm /> matches this search.</p>
      <p v-else class="public-views-status">No one has shared a <AiViewTerm /> yet.</p>
    </section>
  </main>
</template>

<script>
import {
  clearSharedViewsAdminSession,
  hasSharedViewsAdminSession,
  getCollectionSynthesis,
  listManagedViews,
  listPublicViews,
  loginSharedViewsAdmin,
  reorderManagedViews,
  updateManagedView,
  updateCollectionSynthesis,
} from '../utils/viewShareSite';
import scrollRevealMixin from '../mixins/scrollRevealMixin';
import AiViewTerm from './ui/AiViewTerm.vue';

export default {
  name: 'PublicViewsPage',
  components: { AiViewTerm },
  mixins: [scrollRevealMixin],
  data() {
    return {
      views: [],
      adminViews: [],
      searchResults: [],
      query: '',
      loading: true,
      searching: false,
      error: '',
      adminMode: false,
      adminLoginOpen: false,
      adminPassword: '',
      adminBusy: false,
      adminError: '',
      pendingViewId: '',
      reading: null,
      readingBusy: false,
      readingMessage: '',
    };
  },
  computed: {
    visibleViews() {
      const query = this.query.toLocaleLowerCase().trim();
      if (this.adminMode) {
        if (!query) return this.adminViews;
        return this.adminViews.filter((view) => `${view.question} ${view.title}`.toLocaleLowerCase().includes(query));
      }
      if (!query) return this.views;
      return this.searchResults;
    },
    publicAdminCount() {
      return this.adminViews.filter((view) => view.visibility === 'public').length;
    },
    hiddenAdminCount() {
      return this.adminViews.length - this.publicAdminCount;
    },
  },
  watch: {
    query() {
      window.clearTimeout(this._searchTimer);
      if (this.adminMode) {
        this.searchResults = [];
        this.searching = false;
        return;
      }
      const sequence = (this._searchSequence || 0) + 1;
      this._searchSequence = sequence;
      if (!this.query.trim()) {
        this.searchResults = [];
        this.searching = false;
        return;
      }
      this.searching = true;
      this._searchTimer = window.setTimeout(async () => {
        try {
          const data = await listPublicViews(this.query.trim());
          if (sequence === this._searchSequence) this.searchResults = data.views || [];
        } catch {
          if (sequence === this._searchSequence) {
            const query = this.query.toLocaleLowerCase().trim();
            this.searchResults = this.views.filter((view) => `${view.question} ${view.title}`.toLocaleLowerCase().includes(query));
          }
        } finally {
          if (sequence === this._searchSequence) this.searching = false;
        }
      }, 220);
    },
  },
  async mounted() {
    await Promise.all([this.refreshViews({ preferCache: true }), this.refreshReading()]);
    if (hasSharedViewsAdminSession()) await this.resumeAdminSession();
    window.addEventListener('pageshow', this.refreshViews);
    window.addEventListener('keydown', this.handleAdminKeydown);
  },
  activated() {
    this.refreshViews();
  },
  beforeUnmount() {
    this._readingDisposed = true;
    window.clearTimeout(this._readingTimer);
    window.clearTimeout(this._searchTimer);
    window.removeEventListener('pageshow', this.refreshViews);
    window.removeEventListener('keydown', this.handleAdminKeydown);
  },
  methods: {
    async refreshReading() {
      window.clearTimeout(this._readingTimer);
      try {
        const data = await getCollectionSynthesis(this.adminMode);
        if (this._readingDisposed) return;
        this.reading = data.synthesis;
        this.readingBusy = data.status === 'preparing';
        if (this.readingBusy) {
          this.readingMessage = 'Looking through recent questions…';
          this._readingTimer = window.setTimeout(() => this.refreshReading(), 3000);
        } else if (data.status === 'failed') {
          this.readingMessage = 'The note could not be updated. Please try again.';
        } else if (data.status === 'ready') {
          this.readingMessage = data.synthesis ? 'The note is published.' : 'Update the note to reflect changes to the collection.';
        }
      } catch (error) {
        if (this._readingDisposed) return;
        this.readingBusy = false;
        if (this.adminMode) this.readingMessage = error?.message === 'forbidden'
          ? 'Sign in again to update the note.'
          : 'The note is temporarily unavailable. Try updating it again.';
      }
    },
    async updateReading() {
      if (this.readingBusy) return;
      this.readingBusy = true;
      this.readingMessage = 'Looking through recent questions…';
      try {
        await updateCollectionSynthesis(crypto.randomUUID());
        await this.refreshReading();
      } catch (error) {
        if (error?.message === 'synthesis_busy') return this.refreshReading();
        this.readingBusy = false;
        this.readingMessage = error?.message === 'forbidden'
          ? 'Sign in again to update the note.'
          : 'The note could not be updated. Please try again.';
      }
    },
    async refreshViews({ preferCache = false } = {}) {
      if (this.adminMode) return this.refreshAdminViews();
      const sequence = (this._refreshSequence || 0) + 1;
      this._refreshSequence = sequence;
      this.loading = true;
      this.error = '';
      try {
        const query = this.query.trim();
        const [collection, search] = await Promise.all([
          listPublicViews('', { preferCache }),
          query ? listPublicViews(query) : Promise.resolve(null),
        ]);
        if (sequence !== this._refreshSequence) return;
        this.views = collection.views || [];
        if (search) this.searchResults = search.views || [];
      } catch {
        if (sequence === this._refreshSequence) this.error = 'Public Views are temporarily unavailable.';
      } finally {
        if (sequence === this._refreshSequence) this.loading = false;
      }
    },
    openAdminLogin() {
      if (this.adminMode) return;
      this.adminLoginOpen = true;
      this.adminError = '';
      this.$nextTick(() => this.$refs.adminPassword?.focus());
    },
    closeAdminLogin() {
      if (this.adminBusy) return;
      this.adminLoginOpen = false;
      this.adminPassword = '';
      this.adminError = '';
    },
    handleAdminKeydown(event) {
      if (event.key === 'Escape' && this.adminLoginOpen && !this.adminBusy) this.closeAdminLogin();
    },
    async loginAdmin() {
      if (!this.adminPassword || this.adminBusy) return;
      this.adminBusy = true;
      this.adminError = '';
      try {
        await loginSharedViewsAdmin(this.adminPassword);
        this.adminMode = true;
        this.adminLoginOpen = false;
        this.adminPassword = '';
        await this.refreshAdminViews();
      } catch (error) {
        this.adminError = error?.message === 'too_many_attempts'
          ? 'Too many attempts. Wait a moment and try again.'
          : 'That password did not work.';
      } finally {
        this.adminBusy = false;
      }
    },
    async resumeAdminSession() {
      try {
        this.adminMode = true;
        await this.refreshAdminViews();
      } catch {
        await this.signOutAdmin();
      }
    },
    async refreshAdminViews() {
      this.loading = true;
      this.error = '';
      try {
        const data = await listManagedViews();
        this.adminViews = data.views || [];
        await this.refreshReading();
      } catch (error) {
        if (error?.message === 'forbidden') {
          clearSharedViewsAdminSession();
          this.adminMode = false;
          throw error;
        }
        this.error = 'Collection management is temporarily unavailable.';
      } finally {
        this.loading = false;
      }
    },
    async signOutAdmin() {
      clearSharedViewsAdminSession();
      this.adminMode = false;
      this.adminViews = [];
      this.pendingViewId = '';
      this.readingMessage = '';
      this.readingBusy = false;
      window.clearTimeout(this._readingTimer);
      await this.refreshViews();
    },
    publicPosition(id) {
      return this.adminViews.filter((view) => view.visibility === 'public').findIndex((view) => view.id === id);
    },
    async persistPublicOrder(ordered) {
      const hidden = this.adminViews.filter((view) => view.visibility !== 'public');
      const previous = this.adminViews;
      this.adminViews = [...ordered, ...hidden];
      this.pendingViewId = 'order';
      try {
        await reorderManagedViews(ordered.map((view) => view.id));
      } catch {
        this.adminViews = previous;
        this.error = 'The new order could not be saved. Please try again.';
      } finally {
        this.pendingViewId = '';
      }
    },
    moveView(view, direction) {
      const ordered = this.adminViews.filter((item) => item.visibility === 'public');
      const index = ordered.findIndex((item) => item.id === view.id);
      const target = index + direction;
      if (index < 0 || target < 0 || target >= ordered.length) return;
      [ordered[index], ordered[target]] = [ordered[target], ordered[index]];
      this.persistPublicOrder(ordered);
    },
    pinView(view) {
      const ordered = this.adminViews.filter((item) => item.visibility === 'public' && item.id !== view.id);
      this.persistPublicOrder([view, ...ordered]);
    },
    async toggleViewVisibility(view) {
      this.pendingViewId = view.id;
      this.error = '';
      try {
        await updateManagedView(view.id, view.visibility === 'public' ? 'hide' : 'publish');
        await this.refreshAdminViews();
      } catch {
        this.error = 'That change could not be saved. Please try again.';
      } finally {
        this.pendingViewId = '';
      }
    },
    async deleteView(view) {
      if (!window.confirm(`Delete “${view.title}” permanently? This also removes its shared link.`)) return;
      this.pendingViewId = view.id;
      this.error = '';
      try {
        await updateManagedView(view.id, 'delete');
        this.adminViews = this.adminViews.filter((item) => item.id !== view.id);
        await this.refreshReading();
      } catch {
        this.error = 'This View could not be deleted. Please try again.';
      } finally {
        this.pendingViewId = '';
      }
    },
    sourceLabel(count) {
      return `${count} original ${count === 1 ? 'piece' : 'pieces'}`;
    },
    dateLabel(timestamp) {
      if (!timestamp) return 'Date unavailable';
      return new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })
        .format(new Date(timestamp));
    },
    createOwnView() {
      window.dispatchEvent(new CustomEvent('open-site-view'));
    },
  },
};
</script>

