<template>
  <div v-if="images.length" class="figure-sequence" :class="{ 'is-paper': paper, 'is-compact': compact, 'has-side-tabs': sideTabs }" @click.stop @keydown.stop>
    <div :id="`${uid}-panel`" class="figure-sequence-panel" role="tabpanel" :aria-labelledby="images.length > 1 ? `${uid}-tab-${active}` : null" :aria-label="images.length > 1 ? null : title" tabindex="0">
      <div class="figure-sequence-stage" :class="{ 'is-document': current.fit === false }">
        <Transition v-if="compact" name="figure-change" :css="animateChange">
          <ExpandableProjectImage :key="current.fullSrc" :src="current.fullSrc" :alt="current.alt" :title="current.label || title" :fit="current.fit !== false" />
        </Transition>
        <ExpandableProjectImage v-else :key="current.fullSrc" :src="current.fullSrc" :alt="current.alt" :title="current.label || title" :fit="current.fit !== false" />
      </div>
      <div v-if="compact" class="figure-sequence-note">
        <p class="figure-sequence-label">{{ current.label }}<span v-if="images.length > 1">{{ String(active + 1).padStart(2, '0') }} / {{ String(images.length).padStart(2, '0') }}</span></p>
        <p v-if="current.caption" class="figure-sequence-caption">{{ current.caption }}</p>
      </div>
      <p v-else-if="current.caption" class="figure-sequence-caption">{{ current.caption }}</p>
    </div>
    <div v-if="images.length > 1" class="figure-sequence-tabs" role="tablist" :aria-label="`${title} figures`" @keydown="onTabKey">
      <button v-for="(figure, index) in images" :id="`${uid}-tab-${index}`" :key="figure.fullSrc" type="button" role="tab" :aria-selected="active === index" :tabindex="active === index ? 0 : -1" :aria-controls="`${uid}-panel`" :title="compact ? figure.label : null" @click="selectFigure(index, $event)">
        <span class="figure-sequence-thumb"><img :src="figure.src" alt="" loading="lazy" /></span>
        <span :class="{ 'figure-sequence-sr-label': compact }">{{ figure.label || `Figure ${index + 1}` }}</span>
      </button>
    </div>
  </div>
</template>

<script>
import ExpandableProjectImage from './ExpandableProjectImage.vue';

export default {
  name: 'FigureSequence',
  components: { ExpandableProjectImage },
  props: {
    images: { type: Array, required: true },
    title: { type: String, required: true },
    paper: { type: Boolean, default: false },
    compact: { type: Boolean, default: false },
    sideTabs: { type: Boolean, default: false },
    initialLabel: { type: String, default: '' },
  },
  data() { return { active: Math.max(0, this.images.findIndex(image => image.label === this.initialLabel)), animateChange: true }; },
  computed: {
    uid() { return `figure-sequence-${this.$.uid}`; },
    current() { return this.images[this.active] || this.images[0]; },
  },
  watch: {
    images() { if (this.active >= this.images.length) this.active = 0; },
  },
  methods: {
    selectFigure(index, event) { this.animateChange = event.detail !== 0; this.active = index; },
    onTabKey(event) {
      if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
      event.preventDefault();
      this.animateChange = false;
      if (event.key === 'Home') this.active = 0;
      else if (event.key === 'End') this.active = this.images.length - 1;
      else this.active = (this.active + (event.key === 'ArrowRight' ? 1 : -1) + this.images.length) % this.images.length;
      this.$nextTick(() => this.$el.querySelector(`#${this.uid}-tab-${this.active}`)?.focus({ preventScroll: true }));
    },
  },
};
</script>

