.figure-sequence-tabs { display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); gap: 16px; margin-top: 14px; }
.figure-sequence-tabs button { display: flex; align-items: center; gap: 10px; min-width: 0; min-height: 48px; padding: 8px 0 12px; border: 0; border-bottom: 1px solid transparent; background: none; color: var(--site-text-tertiary); text-align: left; font: 12px/1.4 'Quattrocento Sans', sans-serif; cursor: var(--site-interactive-cursor); transition: color 160ms ease, border-color 160ms ease; }
