.figure-sequence-thumb img { position: absolute; inset: 0; display: block; width: 100%; height: 100%; min-width: 0; min-height: 0; max-height: 100%; margin: 0; object-fit: contain; border-radius: 0; }
.figure-sequence-tabs button:focus-visible, .figure-sequence-panel:focus-visible { outline: 2px solid currentColor; outline-offset: 4px; }
@media (hover: hover) and (pointer: fine) { .figure-sequence-tabs button:hover { color: var(--site-text-primary); } }
@container (max-width: 520px) {
  .figure-sequence-tabs { grid-template-columns: repeat(2,minmax(0,1fr)); gap: 8px 16px; }
  .figure-sequence-caption { min-height: 0; }
}
.is-compact { display: grid; grid-template-rows: auto auto; row-gap: 12px; }
.is-compact .figure-sequence-panel { display: contents; }
