.is-compact .figure-sequence-tabs { grid-row: 2; display: flex; flex-wrap: wrap; align-items: start; gap: 10px; margin: 0; padding: 2px 0 0; overflow: visible; }
.is-compact .figure-sequence-tabs button { position: relative; display: block; flex: 0 1 64px; min-width: 44px; height: 54px; min-height: 54px; padding: 0 0 10px; border: 0; opacity: .72; transition: opacity 160ms ease; }
.is-compact .figure-sequence-thumb { width: 100%; height: 42px; transition: transform 180ms cubic-bezier(.23, 1, .32, 1); }
