.is-compact.has-side-tabs [aria-selected="true"] .figure-sequence-thumb { border-color: color-mix(in srgb, var(--site-text-primary) 45%, transparent); }
.is-compact.has-side-tabs .figure-sequence-tabs button::after { bottom: -1px; }
.is-compact.has-side-tabs .figure-sequence-note { grid-column: 1; grid-row: 2; min-height: 64px; }
@media (max-width: 600px) {
  .is-compact.has-side-tabs { --figure-preview-height: calc(100cqw * .7375); grid-template-columns: minmax(0, 1fr); }
  .is-compact.has-side-tabs .figure-sequence-tabs { grid-column: 1; grid-row: 2; height: auto; flex-direction: row; flex-wrap: wrap; }
